window._BOOKS_ = {
    "LEO": {
        "EARLY-SUCCESS": {
            "_1": "data:image/png;base64,",
            "_3": "data:image/png;base64,",
            "_5": "data:image/png;base64,",
            "_7": "data:image/png;base64,",
            "_9": "data:image/png;base64,",
            "_11": "data:image/png;base64,",
            "_13": "data:image/png;base64,",
        }
    },
    "EMPTY": "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABQAAAAUCAYAAACNiR0NAAAAGUlEQVR42u3BAQ0AAADCoPdPbQ43oAAAAAAAAAB4G4YAAAE5zXzKAAAAAElFTkSuQmCC",
    "CAMISETA": "data:image/png;base64,",

    elBookTitle: [],   // Array plano de <input>
    elBookCover: [],   // Array plano de <img>
    /**
     * Inicializa los arrays de elementos.
     *
     * Acepta DOS firmas:
     *   setInit({ selectorBookTitle, selectorBookCover })
     *   setInit(selectorBookTitle, selectorBookCover)
     *
     * Cada selector puede apuntar:
     *   - Directo al elemento   → '#container-imputs input[type="text"]'
     *   - Al contenedor padre    → '#container-imputs'
     * En ambos casos se resuelven TODOS los <input> / <img> implicados.
     */
    setInit(arg1 = {}, arg2 = null) {
        // --- Normalizar firma (objeto vs posicional) ---
        let selectorBookTitle = null;
        let selectorBookCover = null;

        if (typeof arg1 === 'string' || arg1 instanceof Element) {
            selectorBookTitle = arg1;
            selectorBookCover = arg2;
        } else {
            selectorBookTitle = arg1.selectorBookTitle ?? null;
            selectorBookCover = arg1.selectorBookCover ?? null;
        }

        // Reiniciar para no acumular entre llamadas
        this.elBookTitle = [];
        this.elBookCover = [];

        /* =========================================================
         *  BOOK TITLE  →  recolectar <input>
         * ========================================================= */
        if (selectorBookTitle) {
            const roots = this._resolveRoots_(selectorBookTitle);

            roots.forEach(el => {
                // Si el propio nodo es un <input>
                if (el.tagName && el.tagName.toLowerCase() === 'input') {
                    this.elBookTitle.push(el);
                    return;
                }
                // Si es contenedor (o cualquier otro tag), buscamos dentro
                const inputs = el.querySelectorAll?.('input');
                if (inputs && inputs.length > 0) {
                    inputs.forEach(inp => this.elBookTitle.push(inp));
                }
            });

            // Estado inicial
            this.elBookTitle.forEach(inp => {
                inp.value = '';
                inp.readOnly = true;
                inp.disabled = true;
            });
        }

        /* =========================================================
         *  BOOK COVER  →  recolectar <img>
         * ========================================================= */
        if (selectorBookCover) {
            const roots = this._resolveRoots_(selectorBookCover);

            roots.forEach(el => {
                // Si el propio nodo es una <img>
                if (el.tagName && el.tagName.toLowerCase() === 'img') {
                    this.elBookCover.push(el);
                    return;
                }
                // Si es contenedor, buscamos <img> dentro
                const imgs = el.querySelectorAll?.('img');
                if (imgs && imgs.length > 0) {
                    imgs.forEach(img => this.elBookCover.push(img));
                } else {
                    // No hay imagen → creamos una y la inyectamos
                    const newImg = document.createElement('img');
                    el.appendChild(newImg);
                    this.elBookCover.push(newImg);
                }
            });

            // Estado inicial
            this.elBookCover.forEach(img => {
                img.src = this.EMPTY ?? '#empty';
            });
        }
    },

    /**
     * Convierte un selector (string) o un Element en un array de elementos raíz.
     */
    _resolveRoots_(selector) {
        if (selector instanceof Element) return [selector];
        if (typeof selector !== 'string') return [];
        return Array.from(document.querySelectorAll(selector));
    },

    /**
     * Limpia campos y portadas.
     */
    clearBook() {
        this.elBookCover.forEach(img => {
            if (img.tagName?.toLowerCase() === 'img') {
                img.src = this.EMPTY ?? '#empty';
            }
        });

        this.elBookTitle.forEach(inp => {
            inp.value = '';
        });
    },

    /**
     * Carga portada y título según sede/categoría/nivel.
     */
    loadBook({ sede = null, category = null, level = null, bookTitle = null } = {}) {
        if (!sede || !category || !level) return;

        const src = (level !== '_14')
            ? this[sede]?.[category]?.[level] ?? this.EMPTY
            : this.CAMISETA;

        // Portadas
        this.elBookCover.forEach(img => {
            img.src = src;
        });

        // Título
        if (bookTitle) {
            this.elBookTitle.forEach(inp => {
                inp.value = bookTitle;
                inp.readOnly = true;
                inp.disabled = true;
            });
        }
    }
};